package org.zhixiaoce.aperture;
import java.util.concurrent.atomic.AtomicLong;
public class PairWindowTest {
 static int n;static void check(boolean b,String s){n++;if(!b)throw new AssertionError(s);}static void reject(Runnable r,String s){boolean rejected=false;try{r.run();}catch(SecurityException expected){rejected=true;}check(rejected,s);}
 public static void main(String[] a){AtomicLong now=new AtomicLong(1000);LocalControlSession s=new LocalControlSession(now::get);String pin=s.begin();now.addAndGet(299999);String ticket=s.request(pin);check(s.claim(ticket).isEmpty(),"4:59.999 code accepted but requires TV approval");s.close();now.set(1000);pin=s.begin();final String atFive=pin;now.addAndGet(300000);reject(()->s.request(atFive),"5:00.000 code rejected");pin=s.begin();ticket=s.request(pin);now.addAndGet(60000);final String expiredTicket=ticket;reject(()->s.claim(expiredTicket),"confirmation ticket remains 60 seconds");
 pin=s.begin();ticket=s.request(pin);s.approve(ticket,true);String token=s.claim(ticket);check(s.authorized(token),"approved token works");now.addAndGet(1799999);check(s.authorized(token),"approved session lasts 30 minutes");now.incrementAndGet();check(!s.authorized(token),"session expires at 30 minutes");pin=s.begin();final String valid=pin;for(int i=0;i<5;i++)reject(()->s.request(valid.equals("000000")?"000001":"000000"),"wrong code rejected");reject(()->s.request(valid),"five wrong attempts close window");s.begin();s.close();reject(()->s.request(valid),"closing revokes pairing immediately");System.out.println(n+" pairing window boundary/approval/expiry/revocation assertions passed");}
}
